import type { CalendarConfig } from '../types';

const MS_PER_DAY = 86_400_000;
const ORIGIN = '2000-01-01';
const MAX_SCAN = 500_000;
const MAX_STEP = 5_000;

export const MIN_DATE = ORIGIN;

const DAY_NAMES = ['Min', 'Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab'];
const DAY_FULL = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
const MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Agu', 'Sep', 'Okt', 'Nov', 'Des'];

export function pad2(n: number): string {
  return String(n).padStart(2, '0');
}

export function parseISO(iso: string): Date {
  const parts = iso.split('-').map(Number);
  const y = parts[0] ?? 1970;
  const m = parts[1] ?? 1;
  const d = parts[2] ?? 1;
  return new Date(Date.UTC(y, m - 1, d));
}

export function toISODate(date: Date): string {
  return `${date.getUTCFullYear()}-${pad2(date.getUTCMonth() + 1)}-${pad2(date.getUTCDate())}`;
}

export function isValidISO(iso: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(iso)) return false;
  const d = parseISO(iso);
  return !Number.isNaN(d.getTime()) && toISODate(d) === iso;
}

export function addDays(iso: string, n: number): string {
  const d = parseISO(iso);
  d.setUTCDate(d.getUTCDate() + n);
  return toISODate(d);
}

export function dayDiff(from: string, to: string): number {
  return Math.round((parseISO(to).getTime() - parseISO(from).getTime()) / MS_PER_DAY);
}

export function dayOfWeek(iso: string): number {
  return parseISO(iso).getUTCDay();
}

export function todayISO(): string {
  const d = new Date();
  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
}

// ---------------------------------------------------------------------------
// Kalender kerja
// ---------------------------------------------------------------------------

export function isWeekendDay(iso: string, cal: CalendarConfig): boolean {
  return cal.weekendDays.includes(dayOfWeek(iso));
}

export function getHoliday(iso: string, cal: CalendarConfig): string | null {
  const hit = cal.holidays.find((h) => h.date === iso);
  return hit ? hit.name : null;
}

export function isWorkingDay(iso: string, cal: CalendarConfig): boolean {
  if (!isValidISO(iso)) return false;
  if (cal.weekendDays.includes(dayOfWeek(iso))) return false;
  return !cal.holidays.some((h) => h.date === iso);
}

export function nextWorkingDay(iso: string, cal: CalendarConfig): string {
  let cur = isValidISO(iso) ? iso : ORIGIN;
  for (let i = 0; i < MAX_STEP; i++) {
    if (isWorkingDay(cur, cal)) return cur;
    cur = addDays(cur, 1);
  }
  return cur;
}

export function prevWorkingDay(iso: string, cal: CalendarConfig): string {
  let cur = isValidISO(iso) ? iso : ORIGIN;
  for (let i = 0; i < MAX_STEP; i++) {
    if (isWorkingDay(cur, cal)) return cur;
    cur = addDays(cur, -1);
  }
  return cur;
}

// ---------------------------------------------------------------------------
// Indeks hari kerja (urutan hari kerja sejak ORIGIN) untuk perhitungan CPM
// ---------------------------------------------------------------------------

interface IndexCache {
  key: string;
  /** Daftar tanggal hari kerja dari ORIGIN, terurut naik. */
  days: string[];
  /** Jumlah hari kalender dari ORIGIN yang sudah dipindai. */
  scanned: number;
}

let cache: IndexCache = { key: '', days: [], scanned: 0 };

function configKey(cal: CalendarConfig): string {
  const we = [...cal.weekendDays].sort((a, b) => a - b).join(',');
  const ho = cal.holidays.map((h) => h.date).sort().join(',');
  return `${we}#${ho}`;
}

function ensureCache(cal: CalendarConfig): IndexCache {
  const key = configKey(cal);
  if (cache.key !== key) cache = { key, days: [], scanned: 0 };
  return cache;
}

/** Pindai hari kalender dari ORIGIN sampai (tidak termasuk) untilISO. */
function scan(c: IndexCache, cal: CalendarConfig, untilISO: string): void {
  const target = dayDiff(ORIGIN, untilISO);
  if (target <= c.scanned) return;
  const limit = Math.min(target, c.scanned + MAX_SCAN);
  while (c.scanned < limit) {
    const iso = addDays(ORIGIN, c.scanned);
    if (isWorkingDay(iso, cal)) c.days.push(iso);
    c.scanned += 1;
  }
}

/**
 * Peringkat hari kerja: jumlah hari kerja di [ORIGIN, iso).
 * Untuk tanggal non-kerja hasilnya sama dengan peringkat hari kerja
 * berikutnya (efektif membulatkan ke atas ke hari kerja).
 */
export function toIndex(iso: string, cal: CalendarConfig): number {
  if (!isValidISO(iso)) return 0;
  if (iso <= ORIGIN) return 0;
  const c = ensureCache(cal);
  scan(c, cal, iso);
  let lo = 0;
  let hi = c.days.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (c.days[mid] < iso) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

/** Tanggal hari kerja ke-i (0-based) sejak ORIGIN. */
export function fromIndex(index: number, cal: CalendarConfig): string {
  if (index < 0) return ORIGIN;
  const c = ensureCache(cal);
  let guard = 0;
  while (c.days.length <= index && guard < MAX_SCAN) {
    scan(c, cal, addDays(ORIGIN, c.scanned + 1));
    guard += 1;
  }
  return c.days[index] ?? c.days[c.days.length - 1] ?? ORIGIN;
}

/** Maju mundur n hari kerja dari tanggal (tanggal dibulatkan ke hari kerja). */
export function addWorkdays(iso: string, n: number, cal: CalendarConfig): string {
  const base = nextWorkingDay(iso, cal);
  const idx = toIndex(base, cal) + Math.round(n);
  return fromIndex(idx, cal);
}

/** Akhir tugas: durasi hari kerja, hari pertama = hari kerja pertama >= start. */
export function durationEndDate(start: string, duration: number, cal: CalendarConfig): string {
  const dur = Math.max(1, Math.round(duration));
  const first = nextWorkingDay(start, cal);
  return fromIndex(toIndex(first, cal) + dur - 1, cal);
}

/** Jumlah hari kerja inklusif dari a..b (0 bila b < a atau tak ada hari kerja). */
export function countWorkdaysInclusive(a: string, b: string, cal: CalendarConfig): number {
  if (!isValidISO(a) || !isValidISO(b) || a > b) return 0;
  // toIndex(x) = jumlah hari kerja di [ORIGIN, x) -> hari kerja di [a, b]
  return Math.max(0, toIndex(addDays(b, 1), cal) - toIndex(a, cal));
}

// ---------------------------------------------------------------------------
// Format
// ---------------------------------------------------------------------------

export function formatShort(iso: string): string {
  if (!isValidISO(iso)) return '-';
  const d = parseISO(iso);
  return `${d.getUTCDate()} ${MONTH_NAMES[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
}

export function formatCompact(iso: string): string {
  if (!isValidISO(iso)) return '-';
  const d = parseISO(iso);
  return `${pad2(d.getUTCDate())}/${pad2(d.getUTCMonth() + 1)}/${d.getUTCFullYear()}`;
}

export function dayName(iso: string): string {
  if (!isValidISO(iso)) return '-';
  return DAY_FULL[dayOfWeek(iso)];
}

export function dayLetter(iso: string): string {
  if (!isValidISO(iso)) return '-';
  return DAY_NAMES[dayOfWeek(iso)];
}

export function formatMonthYear(iso: string): string {
  if (!isValidISO(iso)) return '-';
  const d = parseISO(iso);
  const full = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
  return `${full[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
}

export function formatIDR(value: number): string {
  if (!Number.isFinite(value)) return 'Rp 0';
  return `Rp ${Math.round(value).toLocaleString('id-ID')}`;
}

import { describe, expect, it } from 'vitest';
import type { CalendarConfig } from '../types';
import {
  addWorkdays,
  countWorkdaysInclusive,
  dayOfWeek,
  durationEndDate,
  fromIndex,
  isWorkingDay,
  nextWorkingDay,
  toIndex,
} from './calendar';

const cal: CalendarConfig = {
  weekendDays: [0, 6],
  holidays: [{ id: 'h1', date: '2026-10-26', name: 'Libur' }],
};

describe('calendar (hari kerja)', () => {
  it('mengenali akhir pekan dan hari libur', () => {
    expect(dayOfWeek('2026-10-12')).toBe(1); // Senin
    expect(isWorkingDay('2026-10-12', cal)).toBe(true);
    expect(isWorkingDay('2026-10-17', cal)).toBe(false); // Sabtu
    expect(isWorkingDay('2026-10-18', cal)).toBe(false); // Minggu
    expect(isWorkingDay('2026-10-26', cal)).toBe(false); // hari libur custom (Senin)
    expect(isWorkingDay('2026-10-27', cal)).toBe(true);
  });

  it('nextWorkingDay melompati akhir pekan dan hari libur', () => {
    expect(nextWorkingDay('2026-10-17', cal)).toBe('2026-10-19');
    expect(nextWorkingDay('2026-10-25', cal)).toBe('2026-10-27'); // lewat libur 26 Okt
    expect(nextWorkingDay('2026-10-12', cal)).toBe('2026-10-12'); // sudah hari kerja
  });

  it('addWorkdays menghitung mundur hari kerja saja', () => {
    // Senin 12 Okt + 5 hari kerja = Senin 19 Okt
    expect(addWorkdays('2026-10-12', 5, cal)).toBe('2026-10-19');
    expect(addWorkdays('2026-10-12', 0, cal)).toBe('2026-10-12');
    // Jumat 16 Okt + 1 hari kerja = Senin 19 Okt (Sab/Ming dilewati)
    expect(addWorkdays('2026-10-16', 1, cal)).toBe('2026-10-19');
    // dari Senin 26 Okt (libur) dibulatkan ke Selasa 27
    expect(addWorkdays('2026-10-26', 1, cal)).toBe('2026-10-28');
    // mundur
    expect(addWorkdays('2026-10-19', -1, cal)).toBe('2026-10-16');
  });

  it('durationEndDate menghasilkan akhir tugas dalam hari kerja', () => {
    // mulai Senin 12 Okt, durasi 5 hari kerja -> Jumat 16 Okt
    expect(durationEndDate('2026-10-12', 5, cal)).toBe('2026-10-16');
    // durasi 6 hari kerja melewati akhir pekan -> Senin 19 Okt
    expect(durationEndDate('2026-10-12', 6, cal)).toBe('2026-10-19');
    // durasi 1 hari dari tanggal libur -> Selasa 27 Okt (26 libur, naik ke hari kerja)
    expect(durationEndDate('2026-10-26', 1, cal)).toBe('2026-10-27');
  });

  it('countWorkdaysInclusive hanya menghitung hari kerja', () => {
    // 12 Okt s/d 16 Okt = 5 hari kerja
    expect(countWorkdaysInclusive('2026-10-12', '2026-10-16', cal)).toBe(5);
    // 12 Okt s/d 19 Okt = 6 hari kerja (Sab/Ming tidak dihitung)
    expect(countWorkdaysInclusive('2026-10-12', '2026-10-19', cal)).toBe(6);
    // rentang hanya akhir pekan = 0
    expect(countWorkdaysInclusive('2026-10-17', '2026-10-18', cal)).toBe(0);
  });

  it('indeks hari kerja konsisten bolak-balik', () => {
    const idx = toIndex('2026-10-12', cal);
    expect(fromIndex(idx, cal)).toBe('2026-10-12');
    // tanggal akhir pekan memetakan ke hari kerja berikutnya
    expect(toIndex('2026-10-17', cal)).toBe(toIndex('2026-10-19', cal));
  });
});

import type { CalendarConfig, Dependency, Task } from '../types';
import { durationEndDate, fromIndex, toIndex } from './calendar';

export interface TaskSchedule {
  id: string;
  /** Indeks hari kerja (0-based) hari mulai. */
  startIdx: number;
  /** Indeks hari kerja hari selesai (inklusif). */
  endIdx: number;
  start: string;
  end: string;
  lateStartIdx: number;
  lateEndIdx: number;
  /** Jumlah hari kerja yang bisa ditunda (0 = kritis). */
  slack: number;
  critical: boolean;
}

export interface ScheduleResult {
  order: string[];
  schedules: Record<string, TaskSchedule>;
  projectStartIdx: number;
  projectEndIdx: number;
  projectStart: string;
  projectEnd: string;
  /** Durasi proyek dalam hari kerja. */
  projectDuration: number;
  /** rantai jalur kritis (urut dari awal ke akhir). */
  criticalPathIds: string[];
  hasCycle: boolean;
}

/** Urutkan tugas topologis; bila ada siklus, sisa tugas diurutkan apa adanya. */
export function topoSort(tasks: Task[]): { order: string[]; hasCycle: boolean } {
  const byId = new Map(tasks.map((t) => [t.id, t]));
  const indeg = new Map<string, number>();
  const adj = new Map<string, string[]>();
  for (const t of tasks) {
    indeg.set(t.id, 0);
    adj.set(t.id, []);
  }
  for (const t of tasks) {
    for (const dep of t.dependencies) {
      if (dep.taskId === t.id || !byId.has(dep.taskId)) continue;
      indeg.set(t.id, (indeg.get(t.id) ?? 0) + 1);
      adj.get(dep.taskId)!.push(t.id);
    }
  }
  const queue = tasks.filter((t) => (indeg.get(t.id) ?? 0) === 0).map((t) => t.id);
  const order: string[] = [];
  while (queue.length > 0) {
    const id = queue.shift()!;
    order.push(id);
    for (const succ of adj.get(id) ?? []) {
      const n = (indeg.get(succ) ?? 0) - 1;
      indeg.set(succ, n);
      if (n === 0) queue.push(succ);
    }
  }
  const hasCycle = order.length !== tasks.length;
  if (hasCycle) {
    const seen = new Set(order);
    for (const t of tasks) if (!seen.has(t.id)) order.push(t.id);
  }
  return { order, hasCycle };
}

function validDeps(task: Task, known: Set<string>): Dependency[] {
  return task.dependencies.filter((d) => d.taskId !== task.id && known.has(d.taskId));
}

/**
 * Perhitungan CPM pada ruang indeks hari kerja:
 * - Forward pass: earliest start = maks(user start, batas predecessor FS/SS + lag).
 * - Backward pass: latest finish = min(latest start successor - lag), akhir proyek = end terjauh.
 * - Slack = late start - earliest start; slack <= 0 dianggap jalur kritis.
 */
export function computeSchedule(tasks: Task[], cal: CalendarConfig): ScheduleResult {
  const known = new Set(tasks.map((t) => t.id));
  const { order, hasCycle } = topoSort(tasks);

  const startIdx = new Map<string, number>();
  const endIdx = new Map<string, number>();
  const dur = new Map<string, number>();

  // ---- Forward pass ----
  for (const id of order) {
    const task = tasks.find((t) => t.id === id)!;
    const duration = Math.max(1, Math.round(task.duration) || 1);
    dur.set(id, duration);

    let earliest = toIndex(task.startDate, cal);
    for (const dep of validDeps(task, known)) {
      const ps = startIdx.get(dep.taskId);
      const pe = endIdx.get(dep.taskId);
      if (ps === undefined || pe === undefined) continue; // bagian dari siklus
      const lag = Math.max(0, Math.round(dep.lag) || 0);
      const cand = dep.type === 'FS' ? pe + 1 + lag : ps + lag;
      if (cand > earliest) earliest = cand;
    }
    startIdx.set(id, earliest);
    endIdx.set(id, earliest + duration - 1);
  }

  const ends = [...endIdx.values()];
  const starts = [...startIdx.values()];
  const projectEndIdx = ends.length > 0 ? Math.max(...ends) : 0;
  const projectStartIdx = starts.length > 0 ? Math.min(...starts) : 0;

  // ---- Backward pass ----
  const successors = new Map<string, { taskId: string; dep: Dependency }[]>();
  for (const t of tasks) {
    for (const dep of validDeps(t, known)) {
      if (!startIdx.has(dep.taskId)) continue;
      const list = successors.get(dep.taskId) ?? [];
      list.push({ taskId: t.id, dep });
      successors.set(dep.taskId, list);
    }
  }

  const lateStart = new Map<string, number>();
  const lateEnd = new Map<string, number>();
  for (let i = order.length - 1; i >= 0; i--) {
    const id = order[i];
    const duration = dur.get(id) ?? 1;
    const succs = successors.get(id) ?? [];
    if (succs.length === 0) {
      const lf = projectEndIdx;
      lateEnd.set(id, lf);
      lateStart.set(id, lf - duration + 1);
      continue;
    }
    let lf = Number.POSITIVE_INFINITY;
    for (const { taskId, dep } of succs) {
      const ls = lateStart.get(taskId);
      if (ls === undefined) continue;
      const lag = Math.max(0, Math.round(dep.lag) || 0);
      const cand = dep.type === 'FS' ? ls - lag - 1 : ls - lag + duration - 1;
      if (cand < lf) lf = cand;
    }
    if (!Number.isFinite(lf)) lf = projectEndIdx;
    if (lf < (endIdx.get(id) ?? lf)) lf = endIdx.get(id)!; // jangan lebih awal dari earliest
    lateEnd.set(id, lf);
    lateStart.set(id, lf - duration + 1);
  }

  // ---- Bangun hasil ----
  const schedules: Record<string, TaskSchedule> = {};
  for (const task of tasks) {
    const id = task.id;
    const s = startIdx.get(id) ?? 0;
    const e = endIdx.get(id) ?? s;
    const ls = lateStart.get(id) ?? s;
    const le = lateEnd.get(id) ?? e;
    const slack = Math.max(0, ls - s);
    schedules[id] = {
      id,
      startIdx: s,
      endIdx: e,
      start: fromIndex(s, cal),
      end: fromIndex(e, cal),
      lateStartIdx: ls,
      lateEndIdx: le,
      slack,
      critical: slack === 0,
    };
  }

  const criticalPathIds = traceCriticalPath(tasks, schedules, order, projectEndIdx, known);

  return {
    order,
    schedules,
    projectStartIdx,
    projectEndIdx,
    projectStart: fromIndex(projectStartIdx, cal),
    projectEnd: fromIndex(projectEndIdx, cal),
    projectDuration: projectEndIdx - projectStartIdx + 1,
    criticalPathIds,
    hasCycle,
  };
}

/** Telusuri rantai kritis dari tugas akhir proyek mundur ke tugas awal. */
function traceCriticalPath(
  tasks: Task[],
  schedules: Record<string, TaskSchedule>,
  order: string[],
  projectEndIdx: number,
  known: Set<string>,
): string[] {
  const criticalTasks = order.filter((id) => schedules[id]?.critical);
  if (criticalTasks.length === 0) return [];

  let tail = criticalTasks.find((id) => schedules[id].endIdx === projectEndIdx) ?? criticalTasks[criticalTasks.length - 1];
  const chain: string[] = [tail];
  const guard = new Set<string>([tail]);

  while (true) {
    const cur = schedules[tail];
    const task = tasks.find((t) => t.id === tail)!;
    let nextId: string | null = null;
    for (const dep of validDeps(task, known)) {
      const p = schedules[dep.taskId];
      if (!p || !p.critical || guard.has(dep.taskId)) continue;
      const tight =
        dep.type === 'FS'
          ? p.endIdx + 1 + Math.max(0, dep.lag) === cur.startIdx
          : p.startIdx + Math.max(0, dep.lag) === cur.startIdx;
      if (tight) {
        nextId = dep.taskId;
        break;
      }
    }
    if (!nextId) break;
    chain.unshift(nextId);
    guard.add(nextId);
    tail = nextId;
  }
  return chain;
}

/** Hitung akhir tugas berdasarkan durasi hari kerja. */
export function taskEnd(task: Task, cal: CalendarConfig): string {
  return durationEndDate(task.startDate, task.duration, cal);
}

import { describe, expect, it } from 'vitest';
import type { CalendarConfig, Task } from '../types';
import { computeSchedule, topoSort } from './schedule';

const cal: CalendarConfig = { weekendDays: [0, 6], holidays: [] };

function makeTask(partial: Partial<Task> & { id: string; name: string; startDate: string; duration: number }): Task {
  return {
    description: '',
    priority: 'Medium',
    color: '#10b981',
    parentId: null,
    collapsed: false,
    dependencies: [],
    assigneeIds: [],
    progress: 0,
    pert: { optimistic: partial.duration, mostLikely: partial.duration, pessimistic: partial.duration },
    ...partial,
  };
}

describe('topoSort', () => {
  it('mengurutkan tugas sesuai ketergantungan', () => {
    const tasks = [
      makeTask({ id: 'b', name: 'B', startDate: '2026-10-12', duration: 1, dependencies: [{ taskId: 'a', type: 'FS', lag: 0 }] }),
      makeTask({ id: 'a', name: 'A', startDate: '2026-10-12', duration: 1 }),
    ];
    const { order, hasCycle } = topoSort(tasks);
    expect(hasCycle).toBe(false);
    expect(order.indexOf('a')).toBeLessThan(order.indexOf('b'));
  });

  it('mendeteksi siklus', () => {
    const tasks = [
      makeTask({ id: 'a', name: 'A', startDate: '2026-10-12', duration: 1, dependencies: [{ taskId: 'b', type: 'FS', lag: 0 }] }),
      makeTask({ id: 'b', name: 'B', startDate: '2026-10-12', duration: 1, dependencies: [{ taskId: 'a', type: 'FS', lag: 0 }] }),
    ];
    expect(topoSort(tasks).hasCycle).toBe(true);
  });
});

describe('computeSchedule (CPM)', () => {
  it('menjadwalkan rantai FS sederhana', () => {
    const tasks = [
      makeTask({ id: 'a', name: 'A', startDate: '2026-10-12', duration: 3 }), // Sen-Rab
      makeTask({
        id: 'b',
        name: 'B',
        startDate: '2026-10-12',
        duration: 2,
        dependencies: [{ taskId: 'a', type: 'FS', lag: 0 }],
      }),
    ];
    const res = computeSchedule(tasks, cal);
    expect(res.schedules.a.start).toBe('2026-10-12');
    expect(res.schedules.a.end).toBe('2026-10-14');
    // FS tanpa lag: mulai hari kerja berikutnya setelah A selesai
    expect(res.schedules.b.start).toBe('2026-10-15');
    expect(res.schedules.b.end).toBe('2026-10-16');
    expect(res.hasCycle).toBe(false);
  });

  it('menghormati lag (jeda) pada FS', () => {
    const tasks = [
      makeTask({ id: 'a', name: 'A', startDate: '2026-10-12', duration: 2 }),
      makeTask({
        id: 'b',
        name: 'B',
        startDate: '2026-10-12',
        duration: 1,
        dependencies: [{ taskId: 'a', type: 'FS', lag: 3 }],
      }),
    ];
    const res = computeSchedule(tasks, cal);
    // A mulai Sen 12 Okt, 2 hari kerja -> selesai Sel 13 Okt.
    // FS default mulai Rab 14 Okt, +3 hari kerja lag (15, 16, 19) -> Sen 19 Okt.
    expect(res.schedules.a.end).toBe('2026-10-13');
    expect(res.schedules.b.start).toBe('2026-10-19');
  });

  it('mendukung hubungan Start-to-Start dengan lag', () => {
    const tasks = [
      makeTask({ id: 'a', name: 'A', startDate: '2026-10-12', duration: 5 }),
      makeTask({
        id: 'b',
        name: 'B',
        startDate: '2026-10-12',
        duration: 2,
        dependencies: [{ taskId: 'a', type: 'SS', lag: 2 }],
      }),
    ];
    const res = computeSchedule(tasks, cal);
    // B mulai 2 hari kerja setelah A: Rab 14 Okt
    expect(res.schedules.b.start).toBe('2026-10-14');
  });

  it('tanggal mulai manual menjadi batas bawah (tidak dimajukan oleh user)', () => {
    const tasks = [
      makeTask({ id: 'a', name: 'A', startDate: '2026-10-12', duration: 1 }),
      makeTask({
        id: 'b',
        name: 'B',
        startDate: '2026-10-20', // user minta mulai Sel 20 Okt
        duration: 1,
        dependencies: [{ taskId: 'a', type: 'FS', lag: 0 }],
      }),
    ];
    const res = computeSchedule(tasks, cal);
    expect(res.schedules.b.start).toBe('2026-10-20');
  });

  it('menghitung slack dan jalur kritis', () => {
    // Cabang a -> c adalah jalur terpanjang (3+2 = 5 hari kerja).
    // Cabang a -> b lebih pendek (3+1 = 4 hari kerja) sehingga B punya slack.
    const tasks = [
      makeTask({ id: 'a', name: 'A', startDate: '2026-10-12', duration: 3 }),
      makeTask({ id: 'b', name: 'B', startDate: '2026-10-12', duration: 1, dependencies: [{ taskId: 'a', type: 'FS', lag: 0 }] }),
      makeTask({
        id: 'c',
        name: 'C',
        startDate: '2026-10-12',
        duration: 2,
        dependencies: [{ taskId: 'a', type: 'FS', lag: 0 }],
      }),
    ];
    const res = computeSchedule(tasks, cal);
    expect(res.schedules.a.critical).toBe(true);
    expect(res.schedules.c.critical).toBe(true);
    expect(res.schedules.b.critical).toBe(false);
    expect(res.schedules.b.slack).toBeGreaterThan(0);
    expect(res.criticalPathIds).toEqual(['a', 'c']);
    // Proyek: A(3) + C(2) = 5 hari kerja, 12..16 Okt
    expect(res.projectStart).toBe('2026-10-12');
    expect(res.projectEnd).toBe('2026-10-16');
    expect(res.projectDuration).toBe(5);
  });

  it('tahan terhadap data bersiklus tanpa crash', () => {
    const tasks = [
      makeTask({ id: 'a', name: 'A', startDate: '2026-10-12', duration: 1, dependencies: [{ taskId: 'b', type: 'FS', lag: 0 }] }),
      makeTask({ id: 'b', name: 'B', startDate: '2026-10-12', duration: 1, dependencies: [{ taskId: 'a', type: 'FS', lag: 0 }] }),
    ];
    const res = computeSchedule(tasks, cal);
    expect(res.hasCycle).toBe(true);
    expect(res.schedules.a.start).toBeTruthy();
    expect(res.schedules.b.start).toBeTruthy();
  });

  it('durasi proyek melewati akhir pekan dengan benar', () => {
    // Jumat 16 Okt durasi 3 hari kerja -> Jumat(1), Senin(2), Selasa(3) = 20 Okt
    const tasks = [makeTask({ id: 'a', name: 'A', startDate: '2026-10-16', duration: 3 })];
    const res = computeSchedule(tasks, cal);
    expect(res.schedules.a.start).toBe('2026-10-16');
    expect(res.schedules.a.end).toBe('2026-10-20');
    expect(res.projectDuration).toBe(3);
  });
});

import type { CalendarConfig, Task } from '../types';
import { fromIndex, toIndex } from './calendar';
import { topoSort } from './schedule';

export interface PertNode {
  id: string;
  name: string;
  optimistic: number;
  mostLikely: number;
  pessimistic: number;
  /** Durasi ekspektasi (O + 4M + P) / 6. */
  expected: number;
  /** Variasi ((P - O) / 6)^2. */
  variance: number;
  startIdx: number;
  /** Finish time eksklusif (start + expected). */
  endIdx: number;
  lateStart: number;
  slack: number;
  critical: boolean;
  /** Kolom tata letak diagram (level topologis). */
  level: number;
  /** Baris tata letak diagram. */
  row: number;
}

export interface PertEdge {
  from: string;
  to: string;
  type: 'FS' | 'SS';
  lag: number;
  critical: boolean;
}

export interface PertResult {
  nodes: PertNode[];
  nodeById: Record<string, PertNode>;
  edges: PertEdge[];
  expectedDuration: number;
  totalVariance: number;
  stddev: number;
  startIdx: number;
  endIdx: number;
  start: string;
  end: string;
  criticalIds: string[];
}

export function expectedDuration(estimate: { optimistic: number; mostLikely: number; pessimistic: number }): number {
  const o = Math.max(0, estimate.optimistic);
  const m = Math.max(0, estimate.mostLikely);
  const p = Math.max(0, estimate.pessimistic);
  return (o + 4 * m + p) / 6;
}

export function varianceOf(estimate: { optimistic: number; mostLikely: number; pessimistic: number }): number {
  const o = Math.max(0, estimate.optimistic);
  const p = Math.max(0, estimate.pessimistic);
  return ((p - o) / 6) ** 2;
}

/** Estimasi PERT dari task; bila belum diisi, pakai durasi rencana. */
export function estimateOf(task: Task): { optimistic: number; mostLikely: number; pessimistic: number } {
  const base = Math.max(1, task.duration);
  const o = task.pert?.optimistic ?? base;
  const m = task.pert?.mostLikely ?? base;
  const p = task.pert?.pessimistic ?? base;
  return { optimistic: o, mostLikely: m, pessimistic: Math.max(o, p) };
}

/**
 * Diagram PERT: forward/backward pass dengan durasi ekspektasi (float),
 * tata letak berdasarkan level topologis terpanjang.
 */
export function computePert(tasks: Task[], cal: CalendarConfig): PertResult {
  const known = new Set(tasks.map((t) => t.id));
  const { order } = topoSort(tasks);
  const est = new Map<string, ReturnType<typeof estimateOf>>();
  const exp = new Map<string, number>();
  for (const t of tasks) {
    const e = estimateOf(t);
    est.set(t.id, e);
    exp.set(t.id, expectedDuration(e));
  }

  const start = new Map<string, number>();
  const end = new Map<string, number>();
  const level = new Map<string, number>();

  for (const id of order) {
    const task = tasks.find((t) => t.id === id)!;
    let earliest = toIndex(task.startDate, cal);
    let lvl = 0;
    for (const dep of task.dependencies) {
      if (dep.taskId === task.id || !known.has(dep.taskId)) continue;
      const ps = start.get(dep.taskId);
      const pe = end.get(dep.taskId);
      const pl = level.get(dep.taskId) ?? 0;
      if (ps === undefined || pe === undefined) continue;
      const lag = Math.max(0, Math.round(dep.lag) || 0);
      const cand = dep.type === 'FS' ? pe + lag : ps + lag;
      if (cand > earliest) earliest = cand;
      if (pl + 1 > lvl) lvl = pl + 1;
    }
    start.set(id, earliest);
    end.set(id, earliest + (exp.get(id) ?? 1));
    level.set(id, lvl);
  }

  const starts = [...start.values()];
  const ends = [...end.values()];
  const projStart = starts.length > 0 ? Math.min(...starts) : 0;
  const projEnd = ends.length > 0 ? Math.max(...ends) : 0;

  // Backward
  const successors = new Map<string, { taskId: string; dep: { type: 'FS' | 'SS'; lag: number } }[]>();
  for (const t of tasks) {
    if (!known.has(t.id)) continue;
    for (const dep of t.dependencies) {
      if (!start.has(dep.taskId)) continue;
      const list = successors.get(dep.taskId) ?? [];
      list.push({ taskId: t.id, dep: { type: dep.type, lag: Math.max(0, Math.round(dep.lag) || 0) } });
      successors.set(dep.taskId, list);
    }
  }
  const lateStart = new Map<string, number>();
  for (let i = order.length - 1; i >= 0; i--) {
    const id = order[i];
    const duration = exp.get(id) ?? 1;
    const succs = successors.get(id) ?? [];
    if (succs.length === 0) {
      lateStart.set(id, projEnd - duration);
      continue;
    }
    let lf = Number.POSITIVE_INFINITY;
    for (const { taskId, dep } of succs) {
      const ls = lateStart.get(taskId);
      if (ls === undefined) continue;
      const cand = dep.type === 'FS' ? ls - dep.lag : ls - dep.lag + duration;
      if (cand < lf) lf = cand;
    }
    if (!Number.isFinite(lf)) lf = projEnd;
    const es = start.get(id) ?? 0;
    const maxLf = es + duration;
    if (lf < maxLf) lf = maxLf;
    lateStart.set(id, lf - duration);
  }

  // Tata letak: kelompokkan per level, urut sesuai urutan topologis
  const byLevel = new Map<number, string[]>();
  for (const id of order) {
    const lv = level.get(id) ?? 0;
    const list = byLevel.get(lv) ?? [];
    list.push(id);
    byLevel.set(lv, list);
  }
  const rowOf = new Map<string, number>();
  for (const [, ids] of byLevel) {
    ids.forEach((id, i) => rowOf.set(id, i));
  }

  const nodes: PertNode[] = order.map((id) => {
    const task = tasks.find((t) => t.id === id)!;
    const e = est.get(id)!;
    const es = start.get(id) ?? 0;
    const ls = lateStart.get(id) ?? es;
    const slack = Math.max(0, ls - es);
    return {
      id,
      name: task.name,
      optimistic: e.optimistic,
      mostLikely: e.mostLikely,
      pessimistic: e.pessimistic,
      expected: exp.get(id) ?? 1,
      variance: varianceOf(e),
      startIdx: es,
      endIdx: end.get(id) ?? es,
      lateStart: ls,
      slack,
      critical: slack < 1e-6,
      level: level.get(id) ?? 0,
      row: rowOf.get(id) ?? 0,
    };
  });

  const nodeById: Record<string, PertNode> = {};
  for (const n of nodes) nodeById[n.id] = n;

  const edges: PertEdge[] = [];
  for (const t of tasks) {
    if (!known.has(t.id)) continue;
    for (const dep of t.dependencies) {
      if (!known.has(dep.taskId)) continue;
      const p = nodeById[dep.taskId];
      const c = nodeById[t.id];
      if (!p || !c) continue;
      edges.push({
        from: dep.taskId,
        to: t.id,
        type: dep.type,
        lag: Math.max(0, Math.round(dep.lag) || 0),
        critical: p.critical && c.critical,
      });
    }
  }

  const criticalIds = order.filter((id) => nodeById[id]?.critical);
  const criticalVariance = criticalIds.reduce((acc, id) => acc + (nodeById[id]?.variance ?? 0), 0);

  return {
    nodes,
    nodeById,
    edges,
    expectedDuration: projEnd - projStart,
    totalVariance: criticalVariance,
    stddev: Math.sqrt(criticalVariance),
    startIdx: projStart,
    endIdx: projEnd,
    start: fromIndex(Math.round(projStart), cal),
    end: fromIndex(Math.max(0, Math.round(projEnd - 1e-9)), cal),
    criticalIds,
  };
}

import { describe, expect, it } from 'vitest';
import type { CalendarConfig, Task } from '../types';
import { computePert, estimateOf, expectedDuration, varianceOf } from './pert';

const cal: CalendarConfig = { weekendDays: [0, 6], holidays: [] };

function makeTask(partial: Partial<Task> & { id: string; name: string; startDate: string; duration: number }): Task {
  return {
    description: '',
    priority: 'Medium',
    color: '#10b981',
    parentId: null,
    collapsed: false,
    dependencies: [],
    assigneeIds: [],
    progress: 0,
    pert: { optimistic: partial.duration, mostLikely: partial.duration, pessimistic: partial.duration },
    ...partial,
  };
}

describe('PERT (estimasi tiga titik)', () => {
  it('expectedDuration = (O + 4M + P) / 6', () => {
    expect(expectedDuration({ optimistic: 4, mostLikely: 6, pessimistic: 16 })).toBeCloseTo(7.3333, 3);
    expect(expectedDuration({ optimistic: 2, mostLikely: 2, pessimistic: 2 })).toBe(2);
  });

  it('varianceOf = ((P - O) / 6)^2', () => {
    expect(varianceOf({ optimistic: 4, mostLikely: 6, pessimistic: 16 })).toBeCloseTo(4, 5);
    expect(varianceOf({ optimistic: 3, mostLikely: 3, pessimistic: 3 })).toBe(0);
  });

  it('estimateOf memakai durasi rencana bila estimasi kosong', () => {
    const t = makeTask({ id: 'x', name: 'X', startDate: '2026-10-12', duration: 5, pert: { optimistic: 0, mostLikely: 0, pessimistic: 0 } });
    // pert terisi 0 -> expectedDuration tetap pakai nilai task
    expect(estimateOf(t)).toEqual({ optimistic: 0, mostLikely: 0, pessimistic: 0 });
    const t2 = makeTask({ id: 'y', name: 'Y', startDate: '2026-10-12', duration: 5 });
    expect(estimateOf(t2)).toEqual({ optimistic: 5, mostLikely: 5, pessimistic: 5 });
  });

  it('menghitung durasi ekspektasi proyek dan varian jalur kritis', () => {
    const tasks = [
      makeTask({
        id: 'a',
        name: 'A',
        startDate: '2026-10-12',
        duration: 4,
        pert: { optimistic: 2, mostLikely: 4, pessimistic: 6 },
      }),
      makeTask({
        id: 'b',
        name: 'B',
        startDate: '2026-10-12',
        duration: 4,
        dependencies: [{ taskId: 'a', type: 'FS', lag: 0 }],
        pert: { optimistic: 4, mostLikely: 5, pessimistic: 16 },
      }),
    ];
    const res = computePert(tasks, cal);
    const ea = expectedDuration({ optimistic: 2, mostLikely: 4, pessimistic: 6 }); // 4
    const eb = expectedDuration({ optimistic: 4, mostLikely: 5, pessimistic: 16 }); // 6.833
    expect(res.expectedDuration).toBeCloseTo(ea + eb, 6);
    expect(res.nodeById.a.expected).toBeCloseTo(ea, 6);
    expect(res.nodeById.b.expected).toBeCloseTo(eb, 6);
    expect(res.criticalIds).toEqual(['a', 'b']);
    // varian jalur kritis = varian A + varian B
    expect(res.totalVariance).toBeCloseTo(
      varianceOf({ optimistic: 2, mostLikely: 4, pessimistic: 6 }) + varianceOf({ optimistic: 4, mostLikely: 5, pessimistic: 16 }),
      6,
    );
    expect(res.stddev).toBeCloseTo(Math.sqrt(res.totalVariance), 6);
  });

  it('menandai cabang yang lebih pendek sebagai tidak kritis', () => {
    // Jalur terpanjang: a(4) -> c(3) -> d(1) = 8 hari kerja.
    // Cabang a(4) -> b(1) berhenti lebih awal sehingga B punya slack.
    const tasks = [
      makeTask({ id: 'a', name: 'A', startDate: '2026-10-12', duration: 4 }),
      makeTask({ id: 'b', name: 'B', startDate: '2026-10-12', duration: 1, dependencies: [{ taskId: 'a', type: 'FS', lag: 0 }] }),
      makeTask({ id: 'c', name: 'C', startDate: '2026-10-12', duration: 3, dependencies: [{ taskId: 'a', type: 'FS', lag: 0 }] }),
      makeTask({ id: 'd', name: 'D', startDate: '2026-10-12', duration: 1, dependencies: [{ taskId: 'c', type: 'FS', lag: 0 }] }),
    ];
    const res = computePert(tasks, cal);
    expect(res.nodeById.a.critical).toBe(true);
    expect(res.nodeById.c.critical).toBe(true);
    expect(res.nodeById.d.critical).toBe(true);
    expect(res.nodeById.b.critical).toBe(false);
    expect(res.nodeById.b.slack).toBeGreaterThan(0);
  });

  it('tata letak level diagram bertingkat', () => {
    const tasks = [
      makeTask({ id: 'a', name: 'A', startDate: '2026-10-12', duration: 1 }),
      makeTask({ id: 'b', name: 'B', startDate: '2026-10-12', duration: 1, dependencies: [{ taskId: 'a', type: 'FS', lag: 0 }] }),
      makeTask({ id: 'c', name: 'C', startDate: '2026-10-12', duration: 1, dependencies: [{ taskId: 'b', type: 'FS', lag: 0 }] }),
    ];
    const res = computePert(tasks, cal);
    expect(res.nodeById.a.level).toBe(0);
    expect(res.nodeById.b.level).toBe(1);
    expect(res.nodeById.c.level).toBe(2);
    expect(res.edges.some((e) => e.from === 'a' && e.to === 'b')).toBe(true);
  });
});

import type { CalendarConfig, Member, Priority, ProjectState, Task } from '../types';
import { createSeedState } from '../data/seed';

export const STORAGE_KEY = 'freebuff-project-state-v1';

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null;
}

function asString(v: unknown, fallback: string): string {
  return typeof v === 'string' ? v : fallback;
}

function asNumber(v: unknown, fallback: number): number {
  return typeof v === 'number' && Number.isFinite(v) ? v : fallback;
}

const PRIORITIES: Priority[] = ['Low', 'Medium', 'High'];

function normalizeTask(raw: unknown): Task | null {
  if (!isRecord(raw)) return null;
  const id = asString(raw.id, '');
  const name = asString(raw.name, '');
  if (!id || !name) return null;

  const depsRaw = Array.isArray(raw.dependencies) ? raw.dependencies : [];
  const dependencies = depsRaw
    .filter(isRecord)
    .map((d) => ({
      taskId: asString(d.taskId, ''),
      type: d.type === 'SS' ? ('SS' as const) : ('FS' as const),
      lag: Math.max(0, asNumber(d.lag, 0)),
    }))
    .filter((d) => d.taskId !== '');

  const pertRaw = isRecord(raw.pert) ? raw.pert : {};
  const duration = Math.max(1, asNumber(raw.duration, 1));
  const priorityRaw = asString(raw.priority, 'Medium') as Priority;
  const pert = {
    optimistic: Math.max(0, asNumber(pertRaw.optimistic, duration)),
    mostLikely: Math.max(0, asNumber(pertRaw.mostLikely, duration)),
    pessimistic: Math.max(0, asNumber(pertRaw.pessimistic, duration)),
  };

  return {
    id,
    name,
    description: asString(raw.description, ''),
    startDate: asString(raw.startDate, '2026-10-12'),
    duration,
    priority: PRIORITIES.includes(priorityRaw) ? priorityRaw : 'Medium',
    color: asString(raw.color, '#10b981'),
    parentId: typeof raw.parentId === 'string' ? raw.parentId : null,
    collapsed: raw.collapsed === true,
    dependencies,
    assigneeIds: Array.isArray(raw.assigneeIds) ? raw.assigneeIds.filter((x): x is string => typeof x === 'string') : [],
    progress: Math.min(100, Math.max(0, asNumber(raw.progress, 0))),
    pert: {
      ...pert,
      pessimistic: Math.max(pert.pessimistic, pert.optimistic),
    },
  };
}

function normalizeMember(raw: unknown): Member | null {
  if (!isRecord(raw)) return null;
  const id = asString(raw.id, '');
  const name = asString(raw.name, '');
  if (!id || !name) return null;
  return {
    id,
    name,
    email: asString(raw.email, ''),
    role: asString(raw.role, ''),
    salary: Math.max(0, asNumber(raw.salary, 0)),
  };
}

function normalizeCalendar(raw: unknown): CalendarConfig {
  const fallback = createSeedState().calendar;
  if (!isRecord(raw)) return fallback;
  const weekendDays = Array.isArray(raw.weekendDays)
    ? raw.weekendDays.filter((d): d is number => typeof d === 'number' && d >= 0 && d <= 6)
    : fallback.weekendDays;
  const holidays = Array.isArray(raw.holidays)
    ? raw.holidays
        .filter(isRecord)
        .map((h) => ({ id: asString(h.id, ''), date: asString(h.date, ''), name: asString(h.name, 'Libur') }))
        .filter((h) => h.id !== '' && /^\d{4}-\d{2}-\d{2}$/.test(h.date))
    : fallback.holidays;
  return { weekendDays, holidays };
}

export function normalizeState(raw: unknown): ProjectState | null {
  if (!isRecord(raw)) return null;
  const tasksRaw = Array.isArray(raw.tasks) ? raw.tasks : null;
  if (!tasksRaw) return null;
  const membersRaw = Array.isArray(raw.members) ? raw.members : [];
  const seed = createSeedState();
  return {
    projectName: asString(raw.projectName, seed.projectName),
    startDate: asString(raw.startDate, seed.startDate),
    tasks: tasksRaw.map(normalizeTask).filter((t): t is Task => t !== null),
    members: membersRaw.map(normalizeMember).filter((m): m is Member => m !== null),
    calendar: normalizeCalendar(raw.calendar),
  };
}

export function loadState(): ProjectState | null {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    return normalizeState(JSON.parse(raw));
  } catch {
    return null;
  }
}

export function saveState(state: ProjectState): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch {
    // Storage penuh/di-nonaktifkan: abaikan, aplikasi tetap jalan in-memory.
  }
}

export function clearState(): void {
  try {
    window.localStorage.removeItem(STORAGE_KEY);
  } catch {
    // ignore
  }
}

