import { useMemo, useRef, useState } from 'react';
import type { Task } from '../types';
import { PRIORITY_LABELS } from '../types';
import { useStore } from '../state/store';
import {
  addDays,
  countWorkdaysInclusive,
  dayDiff,
  dayLetter,
  durationEndDate,
  formatMonthYear,
  formatShort,
  isWorkingDay,
  nextWorkingDay,
  prevWorkingDay,
  todayISO,
} from '../lib/calendar';

const ROW_H = 40;
const LEFT_W = 340;

interface Row {
  task: Task;
  depth: number;
}

interface DragState {
  taskId: string;
  mode: 'move' | 'start' | 'end';
  originX: number;
  origStart: string;
  origEnd: string;
  origDuration: number;
  deltaDays: number;
}

interface GanttProps {
  onEditTask: (task: Task) => void;
  onAddTask: (parentId: string | null) => void;
  highlightCritical: boolean;
  onToggleHighlight: () => void;
}

function buildRows(tasks: Task[]): Row[] {
  const children = new Map<string, Task[]>();
  const roots: Task[] = [];
  for (const t of tasks) {
    if (t.parentId && tasks.some((p) => p.id === t.parentId)) {
      const list = children.get(t.parentId) ?? [];
      list.push(t);
      children.set(t.parentId, list);
    } else {
      roots.push(t);
    }
  }
  const out: Row[] = [];
  const walk = (task: Task, depth: number) => {
    out.push({ task, depth });
    if (task.collapsed) return;
    for (const child of children.get(task.id) ?? []) walk(child, depth + 1);
  };
  for (const root of roots) walk(root, 0);
  return out;
}

export default function GanttChart({ onEditTask, onAddTask, highlightCritical, onToggleHighlight }: GanttProps) {
  const { state, schedule, updateTask, deleteTask, toggleCollapse } = useStore();
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [colW, setColW] = useState(34);
  const [drag, setDrag] = useState<DragState | null>(null);
  const [query, setQuery] = useState('');
  const scrollRef = useRef<HTMLDivElement | null>(null);

  const rows = useMemo(() => {
    const all = buildRows(state.tasks);
    if (!query.trim()) return all;
    const q = query.trim().toLowerCase();
    return all.filter((r) => r.task.name.toLowerCase().includes(q));
  }, [state.tasks, query]);

  const range = useMemo(() => {
    const scheds = Object.values(schedule.schedules);
    const starts = scheds.map((s) => s.start);
    const ends = scheds.map((s) => s.end);
    const min = starts.length > 0 ? starts.reduce((a, b) => (a < b ? a : b)) : state.startDate;
    const max = ends.length > 0 ? ends.reduce((a, b) => (a > b ? a : b)) : state.startDate;
    const start = addDays(min, -4);
    const end = addDays(max, 8);
    return { start, end, days: dayDiff(start, end) + 1 };
  }, [schedule, state.startDate]);

  const days = useMemo(() => {
    const list: { date: string; dow: number }[] = [];
    for (let i = 0; i < range.days; i++) {
      const date = addDays(range.start, i);
      list.push({ date, dow: new Date(`${date}T00:00:00Z`).getUTCDay() });
    }
    return list;
  }, [range]);

  const months = useMemo(() => {
    const out: { label: string; span: number }[] = [];
    for (const d of days) {
      const label = formatMonthYear(d.date);
      const last = out[out.length - 1];
      if (last && last.label === label) last.span += 1;
      else out.push({ label, span: 1 });
    }
    return out;
  }, [days]);

  const timelineW = range.days * colW;
  const xOf = (date: string) => dayDiff(range.start, date) * colW;

  // ---- Drag / resize ----
  const startDrag = (e: React.PointerEvent, task: Task, mode: DragState['mode']) => {
    e.stopPropagation();
    const sched = schedule.schedules[task.id];
    if (!sched) return;
    // Best-effort: jsdom dan beberapa lingkungan tidak menyediakan pointer capture.
    // Drag tetap berfungsi karena listener menempel langsung pada elemen.
    const el = e.currentTarget as HTMLElement;
    if (typeof el.setPointerCapture === 'function') {
      try {
        el.setPointerCapture(e.pointerId);
      } catch {
        // pointerId tidak valid di lingkungan ini — abaikan
      }
    }
    setDrag({
      taskId: task.id,
      mode,
      originX: e.clientX,
      origStart: sched.start,
      origEnd: sched.end,
      origDuration: task.duration,
      deltaDays: 0,
    });
  };

  const onDragMove = (e: React.PointerEvent) => {
    if (!drag) return;
    const delta = Math.round((e.clientX - drag.originX) / colW);
    if (delta !== drag.deltaDays) setDrag({ ...drag, deltaDays: delta });
  };

  const preview = useMemo(() => {
    if (!drag || drag.deltaDays === 0) return null;
    const d = drag.deltaDays;
    if (drag.mode === 'move') {
      const raw = addDays(drag.origStart, d);
      const start = isWorkingDay(raw, state.calendar) ? raw : d >= 0 ? nextWorkingDay(raw, state.calendar) : prevWorkingDay(raw, state.calendar);
      return { start, end: durationEndDate(start, drag.origDuration, state.calendar), duration: drag.origDuration };
    }
    if (drag.mode === 'end') {
      const raw = addDays(drag.origEnd, d);
      const end = isWorkingDay(raw, state.calendar) ? raw : d >= 0 ? nextWorkingDay(raw, state.calendar) : prevWorkingDay(raw, state.calendar);
      const duration = end < drag.origStart ? 1 : countWorkdaysInclusive(drag.origStart, end, state.calendar);
      return { start: drag.origStart, end: durationEndDate(drag.origStart, duration, state.calendar), duration };
    }
    // resize kiri
    const raw = addDays(drag.origStart, d);
    let start = isWorkingDay(raw, state.calendar) ? raw : d >= 0 ? nextWorkingDay(raw, state.calendar) : prevWorkingDay(raw, state.calendar);
    if (start > drag.origEnd) start = drag.origEnd;
    const duration = countWorkdaysInclusive(start, drag.origEnd, state.calendar);
    return { start, end: drag.origEnd, duration: Math.max(1, duration) };
  }, [drag, state.calendar]);

  const endDrag = () => {
    if (!drag) return;
    if (preview) {
      if (drag.mode === 'move') updateTask(drag.taskId, { startDate: preview.start });
      else if (drag.mode === 'end') updateTask(drag.taskId, { duration: preview.duration });
      else updateTask(drag.taskId, { startDate: preview.start, duration: preview.duration });
    }
    setDrag(null);
  };

  // ---- Panah dependensi ----
  const links = useMemo(() => {
    const rowIndex = new Map(rows.map((r, i) => [r.task.id, i]));
    const out: { key: string; d: string; lag: number; critical: boolean }[] = [];
    for (const row of rows) {
      const targetIdx = rowIndex.get(row.task.id);
      if (targetIdx === undefined) continue;
      const ts = schedule.schedules[row.task.id];
      if (!ts) continue;
      for (const dep of row.task.dependencies) {
        const ps = schedule.schedules[dep.taskId];
        const sourceIdx = rowIndex.get(dep.taskId);
        if (!ps || sourceIdx === undefined) continue;
        const y1 = sourceIdx * ROW_H + ROW_H / 2;
        const y2 = targetIdx * ROW_H + ROW_H / 2;
        const x1 = dep.type === 'FS' ? xOf(ps.end) + colW : xOf(ps.start);
        const x2 = xOf(ts.start);
        const critical = ps.critical && ts.critical;
        let d: string;
        if (dep.type === 'FS' && x2 - x1 >= 16) {
          const midX = x1 + 10;
          d = `M ${x1} ${y1} H ${midX} V ${y2} H ${x2 - 4}`;
        } else {
          const c1 = Math.max(x1 + 24, x1);
          const c2 = Math.min(x2 - 24, x2);
          d = `M ${x1} ${y1} C ${c1} ${y1}, ${c2} ${y2}, ${x2 - 4} ${y2}`;
        }
        out.push({ key: `${dep.taskId}-${row.task.id}`, d, lag: dep.lag, critical });
      }
    }
    return out;
  }, [rows, schedule, colW, range.start]);

  const selectedTask = rows.find((r) => r.task.id === selectedId)?.task ?? null;
  const today = todayISO();
  const todayInRange = today >= range.start && today <= range.end;

  const handleDelete = () => {
    if (!selectedTask) return;
    if (window.confirm(`Hapus tugas "${selectedTask.name}" beserta sub-tugasnya?`)) {
      deleteTask(selectedTask.id);
      setSelectedId(null);
    }
  };

  return (
    <section className="gantt-panel">
      <div className="toolbar">
        <button type="button" className="btn primary" onClick={() => onAddTask(null)}>
          + Tugas baru
        </button>
        <button type="button" className="btn" disabled={!selectedTask} onClick={() => onAddTask(selectedTask?.id ?? null)}>
          + Sub-tugas
        </button>
        <button type="button" className="btn" disabled={!selectedTask} onClick={() => selectedTask && onEditTask(selectedTask)}>
          Edit
        </button>
        <button type="button" className="btn danger" disabled={!selectedTask} onClick={handleDelete}>
          Hapus
        </button>
        <span className="spacer" />
        <input
          className="search"
          placeholder="Cari tugas…"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          aria-label="Cari tugas"
        />
        <label className={`toggle ${highlightCritical ? 'on' : ''}`}>
          <input type="checkbox" checked={highlightCritical} onChange={onToggleHighlight} />
          Sorot jalur kritis
        </label>
        <div className="zoom">
          <button type="button" className="icon-btn" aria-label="Perkecil" onClick={() => setColW((w) => Math.max(16, w - 6))}>
            −
          </button>
          <button type="button" className="icon-btn" aria-label="Perbesar" onClick={() => setColW((w) => Math.min(72, w + 6))}>
            +
          </button>
        </div>
      </div>

      {schedule.hasCycle && (
        <div className="banner warn">Terdeteksi ketergantungan bersiklus pada data tugas. Jadwal ditampilkan sebisanya.</div>
      )}

      <div className="gantt-scroll" ref={scrollRef} data-testid="gantt-scroll">
        <div className="gantt-inner" style={{ width: LEFT_W + timelineW }}>
          <div className="gantt-header">
            <div className="gantt-head-left">
              <span>Tugas</span>
              <span className="muted">Mulai → Selesai</span>
            </div>
            <div className="gantt-head-right" style={{ width: timelineW }}>
              <div className="months">
                {months.map((m, i) => (
                  <div key={`${m.label}-${i}`} className="month" style={{ width: m.span * colW }}>
                    {m.span * colW > 56 ? m.label : ''}
                  </div>
                ))}
              </div>
              <div className="days">
                {days.map((d) => (
                  <div
                    key={d.date}
                    className={`daycell ${d.dow === 0 || d.dow === 6 ? 'weekend' : ''} ${
                      state.calendar.holidays.some((h) => h.date === d.date) ? 'holiday' : ''
                    } ${d.date === today ? 'today' : ''}`}
                    style={{ width: colW }}
                    title={d.date}
                  >
                    {colW >= 22 && <span className="dl">{dayLetter(d.date).slice(0, 1)}</span>}
                    <span className="dn">{d.date.slice(8)}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div className="gantt-body" style={{ height: Math.max(rows.length, 1) * ROW_H }}>
            <svg
              className="gantt-links"
              style={{ left: LEFT_W, width: timelineW, height: Math.max(rows.length, 1) * ROW_H }}
              aria-hidden="true"
            >
              <defs>
                <marker id="arrow" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto">
                  <path d="M0,0 L8,4 L0,8 z" fill="#64748b" />
                </marker>
                <marker id="arrow-crit" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto">
                  <path d="M0,0 L8,4 L0,8 z" fill="#dc2626" />
                </marker>
              </defs>
              {links.map((l) => (
                <path
                  key={l.key}
                  d={l.d}
                  className={`link ${l.critical ? 'crit' : ''}`}
                  fill="none"
                  markerEnd={l.critical ? 'url(#arrow-crit)' : 'url(#arrow)'}
                />
              ))}
            </svg>

            {rows.map((row) => {
              const sched = schedule.schedules[row.task.id];
              if (!sched) return null;
              const isDragging = drag?.taskId === row.task.id;
              const start = isDragging && preview ? preview.start : sched.start;
              const end = isDragging && preview ? preview.end : sched.end;
              const left = xOf(start);
              const width = Math.max(colW * 0.6, xOf(end) + colW - left);
              const children = state.tasks.filter((t) => t.parentId === row.task.id);
              const assignees = state.members.filter((m) => row.task.assigneeIds.includes(m.id));
              return (
                <div
                  key={row.task.id}
                  className={`gantt-row ${selectedId === row.task.id ? 'selected' : ''}`}
                  onClick={() => setSelectedId(row.task.id)}
                  onDoubleClick={() => onEditTask(row.task)}
                >
                  <div className="gantt-row-left" style={{ paddingLeft: 10 + row.depth * 18 }}>
                    {children.length > 0 ? (
                      <button
                        type="button"
                        className="chevron"
                        aria-label={row.task.collapsed ? 'Buka' : 'Tutup'}
                        onClick={(e) => {
                          e.stopPropagation();
                          toggleCollapse(row.task.id);
                        }}
                      >
                        {row.task.collapsed ? '▸' : '▾'}
                      </button>
                    ) : (
                      <span className="chevron empty" />
                    )}
                    <span className="dot" style={{ background: row.task.color }} />
                    <span className="task-name" title={row.task.description || row.task.name}>
                      {row.task.name}
                    </span>
                    <span className="row-meta">
                      {row.task.assigneeIds.length > 0 && (
                        <span className="avatars" title={assignees.map((a) => a.name).join(', ')}>
                          {assignees.slice(0, 3).map((a) => (
                            <span key={a.id} className="avatar">
                              {a.name.slice(0, 1).toUpperCase()}
                            </span>
                          ))}
                        </span>
                      )}
                      <span className={`prio p-${row.task.priority.toLowerCase()}`}>{PRIORITY_LABELS[row.task.priority]}</span>
                      <span className="dates">
                        {sched.start.slice(8)}/{sched.start.slice(5, 7)} → {sched.end.slice(8)}/{sched.end.slice(5, 7)}
                      </span>
                    </span>
                  </div>
                  <div className="gantt-row-right" style={{ width: timelineW }}>
                    <div className="track">
                      {days.map((d) => {
                        const holiday = state.calendar.holidays.some((h) => h.date === d.date);
                        return (
                          <span
                            key={d.date}
                            className={`cell ${!isWorkingDay(d.date, state.calendar) ? 'nonwork' : ''} ${holiday ? 'holiday' : ''}`}
                            style={{ width: colW }}
                          />
                        );
                      })}
                    </div>
                    <div
                      className={`bar ${highlightCritical && sched.critical ? 'critical' : ''} ${isDragging ? 'dragging' : ''}`}
                      style={{ left, width, background: row.task.color }}
                      title={`${row.task.name}\n${formatShort(sched.start)} → ${formatShort(sched.end)} (${row.task.duration} hari kerja)`}
                      onPointerDown={(e) => startDrag(e, row.task, 'move')}
                      onPointerMove={onDragMove}
                      onPointerUp={endDrag}
                      onPointerCancel={endDrag}
                      onDoubleClick={(e) => {
                        e.stopPropagation();
                        onEditTask(row.task);
                      }}
                    >
                      <span
                        className="handle left"
                        onPointerDown={(e) => startDrag(e, row.task, 'start')}
                        onPointerMove={onDragMove}
                        onPointerUp={endDrag}
                        onPointerCancel={endDrag}
                      />
                      <span className="bar-label">{row.task.name}</span>
                      <span
                        className="progress"
                        style={{ width: `${Math.min(100, Math.max(0, row.task.progress))}%` }}
                      />
                      <span
                        className="handle right"
                        onPointerDown={(e) => startDrag(e, row.task, 'end')}
                        onPointerMove={onDragMove}
                        onPointerUp={endDrag}
                        onPointerCancel={endDrag}
                      />
                    </div>
                  </div>
                </div>
              );
            })}

            {rows.length === 0 && <p className="empty-state">Belum ada tugas. Klik “+ Tugas baru”.</p>}
          </div>
        </div>
      </div>

      <div className="legend">
        <span className="legend-item">
          <span className="swatch-inline crit" /> Jalur kritis
        </span>
        <span className="legend-item">
          <span className="swatch-inline nonwork" /> Akhir pekan / libur
        </span>
        <span className="legend-item">Seret bar untuk memindah • Tarik tepi bar untuk ubah durasi • Klik ganda untuk edit</span>
        {todayInRange && <span className="legend-item">Hari ini: {formatShort(today)}</span>}
      </div>
    </section>
  );
}

import { useEffect, useMemo, useState } from 'react';
import type { Dependency, LinkType, Priority, Task } from '../types';
import { COLOR_SWATCHES, PRIORITY_LABELS } from '../types';
import { useStore } from '../state/store';

interface Props {
  task: Task | null;
  defaultParentId?: string | null;
  open: boolean;
  onClose: () => void;
}

interface DepRow {
  taskId: string;
  type: LinkType;
  lag: string;
}

function descendantsOf(tasks: Task[], id: string): Set<string> {
  const out = new Set<string>([id]);
  let grew = true;
  while (grew) {
    grew = false;
    for (const t of tasks) {
      if (t.parentId && out.has(t.parentId) && !out.has(t.id)) {
        out.add(t.id);
        grew = true;
      }
    }
  }
  return out;
}

export default function TaskModal({ task, defaultParentId, open, onClose }: Props) {
  const { state, addTask, updateTask } = useStore();

  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [startDate, setStartDate] = useState('2026-10-12');
  const [duration, setDuration] = useState('3');
  const [priority, setPriority] = useState<Priority>('Medium');
  const [color, setColor] = useState(COLOR_SWATCHES[0]);
  const [parentId, setParentId] = useState<string>('');
  const [progress, setProgress] = useState('0');
  const [assignees, setAssignees] = useState<string[]>([]);
  const [deps, setDeps] = useState<DepRow[]>([]);
  const [optimistic, setOptimistic] = useState('1');
  const [mostLikely, setMostLikely] = useState('3');
  const [pessimistic, setPessimistic] = useState('5');
  const [error, setError] = useState('');

  useEffect(() => {
    if (!open) return;
    setError('');
    if (task) {
      setName(task.name);
      setDescription(task.description);
      setStartDate(task.startDate);
      setDuration(String(task.duration));
      setPriority(task.priority);
      setColor(task.color);
      setParentId(task.parentId ?? '');
      setProgress(String(task.progress));
      setAssignees([...task.assigneeIds]);
      setDeps(task.dependencies.map((d) => ({ taskId: d.taskId, type: d.type, lag: String(d.lag) })));
      setOptimistic(String(task.pert.optimistic));
      setMostLikely(String(task.pert.mostLikely));
      setPessimistic(String(task.pert.pessimistic));
    } else {
      setName('');
      setDescription('');
      setStartDate(state.startDate);
      setDuration('3');
      setPriority('Medium');
      setColor(COLOR_SWATCHES[state.tasks.length % COLOR_SWATCHES.length]);
      setParentId(defaultParentId ?? '');
      setProgress('0');
      setAssignees([]);
      setDeps([]);
      setOptimistic('1');
      setMostLikely('3');
      setPessimistic('5');
    }
  }, [open, task, defaultParentId, state.startDate, state.tasks.length]);

  const blockedParents = useMemo(() => (task ? descendantsOf(state.tasks, task.id) : new Set<string>()), [state.tasks, task]);
  const depCandidates = state.tasks.filter((t) => t.id !== task?.id);

  if (!open) return null;

  const toggleAssignee = (id: string) => {
    setAssignees((prev) => (prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]));
  };

  const submit = () => {
    const trimmed = name.trim();
    if (!trimmed) {
      setError('Nama tugas wajib diisi.');
      return;
    }
    const dur = Math.max(1, Math.round(Number(duration) || 1));
    const numericStart = startDate || state.startDate;

    const seen = new Set<string>();
    const dependencies: Dependency[] = [];
    for (const row of deps) {
      if (!row.taskId || row.taskId === task?.id || seen.has(row.taskId)) continue;
      seen.add(row.taskId);
      dependencies.push({ taskId: row.taskId, type: row.type, lag: Math.max(0, Math.round(Number(row.lag) || 0)) });
    }

    const patch = {
      name: trimmed,
      description: description.trim(),
      startDate: numericStart,
      duration: dur,
      priority,
      color,
      parentId: parentId || null,
      progress: Math.min(100, Math.max(0, Math.round(Number(progress) || 0))),
      assigneeIds: assignees,
      dependencies,
      pert: {
        optimistic: Math.max(0, Number(optimistic) || dur),
        mostLikely: Math.max(0, Number(mostLikely) || dur),
        pessimistic: Math.max(0, Number(pessimistic) || dur),
      },
    };

    if (task) {
      updateTask(task.id, patch);
    } else {
      // addTask mengembalikan id tugas baru; lengkapi field lain lewat updateTask
      const createdId = addTask({
        name: trimmed,
        description: patch.description,
        startDate: numericStart,
        duration: dur,
        priority,
        color,
        parentId: parentId || null,
      });
      updateTask(createdId, patch);
    }
    onClose();
  };

  return (
    <div className="modal-backdrop" role="presentation" onClick={onClose}>
      <div
        className="modal"
        role="dialog"
        aria-modal="true"
        aria-label={task ? 'Edit tugas' : 'Tugas baru'}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="modal-head">
          <h2>{task ? 'Edit Tugas' : 'Tugas Baru'}</h2>
          <button type="button" className="icon-btn" onClick={onClose} aria-label="Tutup">
            ✕
          </button>
        </div>

        <div className="modal-body">
          <label className="field">
            <span>Nama tugas *</span>
            <input value={name} onChange={(e) => setName(e.target.value)} placeholder="Contoh: Desain Wireframe" autoFocus />
          </label>

          <label className="field">
            <span>Deskripsi</span>
            <textarea value={description} onChange={(e) => setDescription(e.target.value)} rows={2} placeholder="Deskripsi singkat" />
          </label>

          <div className="field-row">
            <label className="field">
              <span>Tanggal mulai</span>
              <input type="date" value={startDate} min="2000-01-01" onChange={(e) => setStartDate(e.target.value)} />
            </label>
            <label className="field">
              <span>Durasi (hari kerja)</span>
              <input type="number" min={1} value={duration} onChange={(e) => setDuration(e.target.value)} />
            </label>
            <label className="field">
              <span>Progres (%)</span>
              <input type="number" min={0} max={100} value={progress} onChange={(e) => setProgress(e.target.value)} />
            </label>
          </div>

          <div className="field-row">
            <label className="field">
              <span>Prioritas</span>
              <select value={priority} onChange={(e) => setPriority(e.target.value as Priority)}>
                <option value="Low">{PRIORITY_LABELS.Low}</option>
                <option value="Medium">{PRIORITY_LABELS.Medium}</option>
                <option value="High">{PRIORITY_LABELS.High}</option>
              </select>
            </label>
            <label className="field">
              <span>Induk (sub-tugas)</span>
              <select value={parentId} onChange={(e) => setParentId(e.target.value)}>
                <option value="">— Tugas utama —</option>
                {state.tasks
                  .filter((t) => !blockedParents.has(t.id))
                  .map((t) => (
                    <option key={t.id} value={t.id}>
                      {t.name}
                    </option>
                  ))}
              </select>
            </label>
            <div className="field">
              <span>Warna indikator</span>
              <div className="swatches">
                {COLOR_SWATCHES.map((c) => (
                  <button
                    key={c}
                    type="button"
                    className={`swatch ${color === c ? 'active' : ''}`}
                    style={{ background: c }}
                    aria-label={`Pilih warna ${c}`}
                    onClick={() => setColor(c)}
                  />
                ))}
              </div>
            </div>
          </div>

          <fieldset className="field-block">
            <legend>Predecessor (hubungan antar tugas)</legend>
            {deps.length === 0 && <p className="muted">Belum ada ketergantungan. Tugas ini mandiri.</p>}
            {deps.map((row, i) => (
              <div className="dep-row" key={`${row.taskId}-${i}`}>
                <select
                  value={row.taskId}
                  onChange={(e) => setDeps((prev) => prev.map((d, j) => (j === i ? { ...d, taskId: e.target.value } : d)))}
                  aria-label="Predecessor"
                >
                  <option value="">— Pilih tugas —</option>
                  {depCandidates.map((t) => (
                    <option key={t.id} value={t.id}>
                      {t.name}
                    </option>
                  ))}
                </select>
                <select
                  value={row.type}
                  onChange={(e) => setDeps((prev) => prev.map((d, j) => (j === i ? { ...d, type: e.target.value as LinkType } : d)))}
                  aria-label="Tipe hubungan"
                >
                  <option value="FS">Finish-to-Start (FS)</option>
                  <option value="SS">Start-to-Start (SS)</option>
                </select>
                <input
                  type="number"
                  min={0}
                  value={row.lag}
                  aria-label="Jeda hari kerja"
                  title="Jeda (lag) dalam hari kerja"
                  onChange={(e) => setDeps((prev) => prev.map((d, j) => (j === i ? { ...d, lag: e.target.value } : d)))}
                />
                <button
                  type="button"
                  className="icon-btn"
                  aria-label="Hapus dependensi"
                  onClick={() => setDeps((prev) => prev.filter((_, j) => j !== i))}
                >
                  ✕
                </button>
              </div>
            ))}
            <button
              type="button"
              className="btn ghost"
              onClick={() => setDeps((prev) => [...prev, { taskId: depCandidates[0]?.id ?? '', type: 'FS', lag: '0' }])}
            >
              + Tambah predecessor
            </button>
          </fieldset>

          <fieldset className="field-block">
            <legend>Alokasi anggota tim</legend>
            <div className="chip-wrap">
              {state.members.map((m) => (
                <label key={m.id} className={`chip ${assignees.includes(m.id) ? 'on' : ''}`}>
                  <input
                    type="checkbox"
                    checked={assignees.includes(m.id)}
                    onChange={() => toggleAssignee(m.id)}
                  />
                  {m.name}
                  <span className="chip-role">{m.role}</span>
                </label>
              ))}
              {state.members.length === 0 && <p className="muted">Belum ada anggota. Tambahkan di tab Sumber Daya.</p>}
            </div>
          </fieldset>

          <fieldset className="field-block">
            <legend>Estimasi PERT (hari kerja)</legend>
            <div className="field-row three">
              <label className="field">
                <span>Optimis (O)</span>
                <input type="number" min={0} value={optimistic} onChange={(e) => setOptimistic(e.target.value)} />
              </label>
              <label className="field">
                <span>Paling mungkin (M)</span>
                <input type="number" min={0} value={mostLikely} onChange={(e) => setMostLikely(e.target.value)} />
              </label>
              <label className="field">
                <span>Pesimis (P)</span>
                <input type="number" min={0} value={pessimistic} onChange={(e) => setPessimistic(e.target.value)} />
              </label>
            </div>
          </fieldset>

          {error && <p className="error">{error}</p>}
        </div>

        <div className="modal-foot">
          <button type="button" className="btn ghost" onClick={onClose}>
            Batal
          </button>
          <button type="button" className="btn primary" onClick={submit}>
            {task ? 'Simpan perubahan' : 'Tambah tugas'}
          </button>
        </div>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { formatIDR } from '../lib/calendar';
import { useStore } from '../state/store';

interface Form {
  name: string;
  email: string;
  role: string;
  salary: string;
}

const EMPTY: Form = { name: '', email: '', role: '', salary: '' };

export default function ResourcePanel() {
  const { state, schedule, addMember, updateMember, deleteMember } = useStore();
  const [form, setForm] = useState<Form>(EMPTY);
  const [error, setError] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Form>(EMPTY);

  const submit = () => {
    if (!form.name.trim()) {
      setError('Nama anggota wajib diisi.');
      return;
    }
    if (form.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) {
      setError('Format email tidak valid.');
      return;
    }
    setError('');
    addMember({
      name: form.name.trim(),
      email: form.email.trim(),
      role: form.role.trim() || 'Anggota Tim',
      salary: Math.max(0, Math.round(Number(form.salary) || 0)),
    });
    setForm(EMPTY);
  };

  const startEdit = (id: string) => {
    const m = state.members.find((x) => x.id === id);
    if (!m) return;
    setEditingId(id);
    setEditForm({ name: m.name, email: m.email, role: m.role, salary: String(m.salary) });
  };

  const saveEdit = (id: string) => {
    if (!editForm.name.trim()) return;
    updateMember(id, {
      name: editForm.name.trim(),
      email: editForm.email.trim(),
      role: editForm.role.trim(),
      salary: Math.max(0, Math.round(Number(editForm.salary) || 0)),
    });
    setEditingId(null);
  };

  const allocationOf = (memberId: string) => {
    const tasks = state.tasks.filter((t) => t.assigneeIds.includes(memberId));
    const days = tasks.reduce((sum, t) => sum + (schedule.schedules[t.id] ? t.duration : 0), 0);
    return { tasks, days };
  };

  const totalSalary = state.members.reduce((s, m) => s + m.salary, 0);

  return (
    <section className="panel">
      <header className="panel-head">
        <h2>Sumber Daya (Anggota Tim)</h2>
        <p className="muted">Daftarkan anggota, lalu alokasikan ke tugas lewat dialog edit tugas.</p>
      </header>

      <div className="card">
        <h3>Tambah anggota</h3>
        <div className="form-grid">
          <label className="field">
            <span>Nama *</span>
            <input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="Nama lengkap" />
          </label>
          <label className="field">
            <span>Email</span>
            <input
              type="email"
              value={form.email}
              onChange={(e) => setForm({ ...form, email: e.target.value })}
              placeholder="nama@perusahaan.com"
            />
          </label>
          <label className="field">
            <span>Peran</span>
            <input value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })} placeholder="Contoh: Backend Developer" />
          </label>
          <label className="field">
            <span>Gaji / bulan (Rp)</span>
            <input
              type="number"
              min={0}
              value={form.salary}
              onChange={(e) => setForm({ ...form, salary: e.target.value })}
              placeholder="12000000"
            />
          </label>
        </div>
        {error && <p className="error">{error}</p>}
        <button type="button" className="btn primary" onClick={submit}>
          + Tambah anggota
        </button>
      </div>

      <div className="card">
        <h3>Daftar anggota ({state.members.length})</h3>
        {state.members.length === 0 && <p className="muted">Belum ada anggota terdaftar.</p>}
        {state.members.length > 0 && (
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Nama</th>
                  <th>Email</th>
                  <th>Peran</th>
                  <th className="num">Gaji / bulan</th>
                  <th>Alokasi</th>
                  <th />
                </tr>
              </thead>
              <tbody>
                {state.members.map((m) => {
                  const alloc = allocationOf(m.id);
                  const editing = editingId === m.id;
                  return (
                    <tr key={m.id}>
                      <td>
                        {editing ? (
                          <input value={editForm.name} onChange={(e) => setEditForm({ ...editForm, name: e.target.value })} />
                        ) : (
                          <strong>{m.name}</strong>
                        )}
                      </td>
                      <td>
                        {editing ? (
                          <input value={editForm.email} onChange={(e) => setEditForm({ ...editForm, email: e.target.value })} />
                        ) : (
                          m.email || '—'
                        )}
                      </td>
                      <td>
                        {editing ? (
                          <input value={editForm.role} onChange={(e) => setEditForm({ ...editForm, role: e.target.value })} />
                        ) : (
                          m.role
                        )}
                      </td>
                      <td className="num">
                        {editing ? (
                          <input
                            type="number"
                            min={0}
                            value={editForm.salary}
                            onChange={(e) => setEditForm({ ...editForm, salary: e.target.value })}
                          />
                        ) : (
                          formatIDR(m.salary)
                        )}
                      </td>
                      <td>
                        <span className="muted">
                          {alloc.tasks.length} tugas • {alloc.days} hari kerja
                        </span>
                        <div className="tag-wrap">
                          {alloc.tasks.map((t) => (
                            <span key={t.id} className="tag" style={{ borderColor: t.color }}>
                              {t.name}
                            </span>
                          ))}
                        </div>
                      </td>
                      <td className="actions">
                        {editing ? (
                          <>
                            <button type="button" className="btn small primary" onClick={() => saveEdit(m.id)}>
                              Simpan
                            </button>
                            <button type="button" className="btn small ghost" onClick={() => setEditingId(null)}>
                              Batal
                            </button>
                          </>
                        ) : (
                          <>
                            <button type="button" className="btn small" onClick={() => startEdit(m.id)}>
                              Edit
                            </button>
                            <button
                              type="button"
                              className="btn small danger"
                              onClick={() => {
                                if (window.confirm(`Hapus anggota ${m.name}?`)) deleteMember(m.id);
                              }}
                            >
                              Hapus
                            </button>
                          </>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
              <tfoot>
                <tr>
                  <td colSpan={3}>Total gaji bulanan</td>
                  <td className="num">{formatIDR(totalSalary)}</td>
                  <td colSpan={2} />
                </tr>
              </tfoot>
            </table>
          </div>
        )}
      </div>
    </section>
  );
}

import { useMemo, useState } from 'react';
import { addDays, countWorkdaysInclusive, formatMonthYear, isWorkingDay, pad2, todayISO } from '../lib/calendar';
import { useStore } from '../state/store';

const DAY_LABELS = ['Min', 'Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab'];

export default function CalendarPanel() {
  const { state, schedule, addHoliday, removeHoliday, toggleWeekendDay } = useStore();
  const [date, setDate] = useState(todayISO());
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const [cursor, setCursor] = useState(() => {
    const d = new Date();
    return { year: d.getFullYear(), month: d.getMonth() };
  });

  const submit = () => {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      setError('Pilih tanggal libur terlebih dahulu.');
      return;
    }
    if (!name.trim()) {
      setError('Nama hari libur wajib diisi.');
      return;
    }
    if (state.calendar.holidays.some((h) => h.date === date)) {
      setError('Tanggal tersebut sudah terdaftar sebagai hari libur.');
      return;
    }
    setError('');
    addHoliday(date, name);
    setName('');
  };

  const projectWorkdays = useMemo(() => {
    if (!schedule.projectStart || !schedule.projectEnd) return 0;
    return countWorkdaysInclusive(schedule.projectStart, schedule.projectEnd, state.calendar);
  }, [schedule.projectStart, schedule.projectEnd, state.calendar]);

  const calendarCells = useMemo(() => {
    const first = new Date(Date.UTC(cursor.year, cursor.month, 1));
    const startPad = first.getUTCDay();
    const daysInMonth = new Date(Date.UTC(cursor.year, cursor.month + 1, 0)).getUTCDate();
    const cells: (string | null)[] = [];
    for (let i = 0; i < startPad; i++) cells.push(null);
    for (let d = 1; d <= daysInMonth; d++) cells.push(`${cursor.year}-${pad2(cursor.month + 1)}-${pad2(d)}`);
    return cells;
  }, [cursor]);

  const shiftMonth = (delta: number) => {
    setCursor((c) => {
      const m = c.month + delta;
      return { year: c.year + Math.floor(m / 12), month: ((m % 12) + 12) % 12 };
    });
  };

  const today = todayISO();

  return (
    <section className="panel">
      <header className="panel-head">
        <h2>Kalender Proyek</h2>
        <p className="muted">Durasi selalu dihitung dalam hari kerja — akhir pekan dan hari libur dilewati.</p>
      </header>

      <div className="panel-grid">
        <div className="card">
          <h3>Hari akhir pekan</h3>
          <div className="weekday-toggles">
            {[0, 1, 2, 3, 4, 5, 6].map((d) => {
              const on = state.calendar.weekendDays.includes(d);
              return (
                <button
                  key={d}
                  type="button"
                  className={`chip ${on ? 'on' : ''}`}
                  onClick={() => toggleWeekendDay(d)}
                  aria-pressed={on}
                >
                  {DAY_LABELS[d]}
                </button>
              );
            })}
          </div>
          <p className="muted">
            Aktif: {state.calendar.weekendDays.length === 0 ? 'tidak ada (semua hari kerja)' : state.calendar.weekendDays.map((d) => DAY_LABELS[d]).join(', ')}
          </p>

          <div className="stats">
            <div className="stat">
              <span className="stat-val">{state.calendar.holidays.length}</span>
              <span className="stat-label">Hari libur khusus</span>
            </div>
            <div className="stat">
              <span className="stat-val">{projectWorkdays}</span>
              <span className="stat-label">Hari kerja proyek</span>
            </div>
            <div className="stat">
              <span className="stat-val">{schedule.projectDuration}</span>
              <span className="stat-label">Durasi jadwal (hari kerja)</span>
            </div>
          </div>
        </div>

        <div className="card">
          <h3>Tambah hari libur khusus</h3>
          <div className="form-grid">
            <label className="field">
              <span>Tanggal</span>
              <input type="date" value={date} min="2000-01-01" onChange={(e) => setDate(e.target.value)} />
            </label>
            <label className="field">
              <span>Nama libur</span>
              <input value={name} onChange={(e) => setName(e.target.value)} placeholder="Contoh: Hari Libur Nasional" />
            </label>
          </div>
          {error && <p className="error">{error}</p>}
          <button type="button" className="btn primary" onClick={submit}>
            + Tambah libur
          </button>

          <ul className="holiday-list">
            {state.calendar.holidays.length === 0 && <li className="muted">Belum ada hari libur khusus.</li>}
            {[...state.calendar.holidays]
              .sort((a, b) => a.date.localeCompare(b.date))
              .map((h) => (
                <li key={h.id}>
                  <span className="holiday-date">{h.date}</span>
                  <span>{h.name}</span>
                  <button
                    type="button"
                    className="icon-btn"
                    aria-label={`Hapus libur ${h.name}`}
                    onClick={() => removeHoliday(h.id)}
                  >
                    ✕
                  </button>
                </li>
              ))}
          </ul>
        </div>
      </div>

      <div className="card">
        <div className="cal-head">
          <button type="button" className="icon-btn" aria-label="Bulan sebelumnya" onClick={() => shiftMonth(-1)}>
            ‹
          </button>
          <h3>{formatMonthYear(`${cursor.year}-${pad2(cursor.month + 1)}-01`)}</h3>
          <button type="button" className="icon-btn" aria-label="Bulan berikutnya" onClick={() => shiftMonth(1)}>
            ›
          </button>
        </div>
        <div className="mini-cal">
          {DAY_LABELS.map((d) => (
            <span key={d} className="mini-dow">
              {d}
            </span>
          ))}
          {calendarCells.map((iso, i) => {
            if (!iso) return <span key={`pad-${i}`} className="mini-day empty" />;
            const working = isWorkingDay(iso, state.calendar);
            const holiday = state.calendar.holidays.find((h) => h.date === iso);
            return (
              <span
                key={iso}
                className={`mini-day ${working ? 'work' : 'off'} ${iso === today ? 'today' : ''}`}
                title={holiday ? `${iso} — ${holiday.name}` : iso}
              >
                {Number(iso.slice(8))}
              </span>
            );
          })}
        </div>
        <p className="muted">
          Rentang jadwal: {schedule.projectStart} s/d {schedule.projectEnd} • hari ini {addDays(today, 0)}
        </p>
      </div>
    </section>
  );
}

import { useMemo } from 'react';
import { computePert } from '../lib/pert';
import { formatShort } from '../lib/calendar';
import { useStore } from '../state/store';

const NODE_W = 168;
const NODE_H = 66;
const GAP_X = 78;
const GAP_Y = 22;

export default function AnalysisPanel() {
  const { state, schedule } = useStore();
  const pert = useMemo(() => computePert(state.tasks, state.calendar), [state.tasks, state.calendar]);

  const criticalTasks = schedule.criticalPathIds
    .map((id) => state.tasks.find((t) => t.id === id))
    .filter((t): t is NonNullable<typeof t> => Boolean(t));

  const maxLevel = pert.nodes.reduce((m, n) => Math.max(m, n.level), 0);
  const rowsPerLevel = useMemo(() => {
    const map = new Map<number, number>();
    for (const n of pert.nodes) map.set(n.level, (map.get(n.level) ?? 0) + 1);
    return map;
  }, [pert.nodes]);
  const maxRows = Math.max(1, ...rowsPerLevel.values());
  const svgW = (maxLevel + 1) * (NODE_W + GAP_X) + 40;
  const svgH = maxRows * (NODE_H + GAP_Y) + 40;

  const nodePos = (level: number, row: number) => ({
    x: 24 + level * (NODE_W + GAP_X),
    y: 24 + row * (NODE_H + GAP_Y),
  });

  return (
    <section className="panel">
      <header className="panel-head">
        <h2>Analisis Proyek</h2>
        <p className="muted">Jalur kritis (CPM) dan diagram PERT berdasarkan durasi hari kerja.</p>
      </header>

      <div className="stats wide">
        <div className="stat">
          <span className="stat-val">{schedule.projectDuration}</span>
          <span className="stat-label">Durasi proyek (hari kerja)</span>
        </div>
        <div className="stat">
          <span className="stat-val">{formatShort(schedule.projectStart)}</span>
          <span className="stat-label">Mulai proyek</span>
        </div>
        <div className="stat">
          <span className="stat-val">{formatShort(schedule.projectEnd)}</span>
          <span className="stat-label">Selesai proyek</span>
        </div>
        <div className="stat">
          <span className="stat-val">{criticalTasks.length}</span>
          <span className="stat-label">Tugas jalur kritis</span>
        </div>
        <div className="stat">
          <span className="stat-val">{pert.expectedDuration.toFixed(1)}</span>
          <span className="stat-label">Durasi ekspektasi PERT</span>
        </div>
        <div className="stat">
          <span className="stat-val">±{pert.stddev.toFixed(2)}</span>
          <span className="stat-label">Deviasi standar jalur kritis</span>
        </div>
      </div>

      <div className="panel-grid">
        <div className="card">
          <h3>Jalur Kritis (Critical Path)</h3>
          <p className="muted">Tugas dengan slack = 0. Keterlambatannya langsung menunda akhir proyek.</p>
          {criticalTasks.length === 0 ? (
            <p className="muted">Tidak ada jalur kritis (cek ketergantungan tugas).</p>
          ) : (
            <ol className="critical-list">
              {criticalTasks.map((t) => {
                const s = schedule.schedules[t.id];
                return (
                  <li key={t.id}>
                    <span className="dot" style={{ background: t.color }} />
                    <div>
                      <strong>{t.name}</strong>
                      <div className="muted">
                        {formatShort(s.start)} → {formatShort(s.end)} • {t.duration} hari kerja • slack {s.slack}
                      </div>
                    </div>
                  </li>
                );
              })}
            </ol>
          )}

          <h3 className="mt">Estimasi PERT per tugas</h3>
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Tugas</th>
                  <th className="num">O</th>
                  <th className="num">M</th>
                  <th className="num">P</th>
                  <th className="num">E=(O+4M+P)/6</th>
                  <th className="num">Variance</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {pert.nodes.map((n) => (
                  <tr key={n.id} className={n.critical ? 'row-critical' : ''}>
                    <td>{n.name}</td>
                    <td className="num">{n.optimistic}</td>
                    <td className="num">{n.mostLikely}</td>
                    <td className="num">{n.pessimistic}</td>
                    <td className="num">{n.expected.toFixed(2)}</td>
                    <td className="num">{n.variance.toFixed(2)}</td>
                    <td>{n.critical ? <span className="badge crit">Kritis</span> : <span className="badge">Slack {n.slack.toFixed(1)}</span>}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <div className="card">
          <h3>Diagram PERT</h3>
          <p className="muted">Kotak merah = jalur kritis. Panah FS/SS dengan jeda (lag) hari kerja.</p>
          <div className="pert-scroll">
            <svg width={svgW} height={svgH} role="img" aria-label="Diagram PERT">
              <defs>
                <marker id="pert-arrow" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto">
                  <path d="M0,0 L8,4 L0,8 z" fill="#64748b" />
                </marker>
                <marker id="pert-arrow-crit" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto">
                  <path d="M0,0 L8,4 L0,8 z" fill="#dc2626" />
                </marker>
              </defs>
              {pert.edges.map((e) => {
                const from = pert.nodeById[e.from];
                const to = pert.nodeById[e.to];
                if (!from || !to) return null;
                const a = nodePos(from.level, from.row);
                const b = nodePos(to.level, to.row);
                const x1 = a.x + NODE_W;
                const y1 = a.y + NODE_H / 2;
                const x2 = b.x;
                const y2 = b.y + NODE_H / 2;
                const midX = Math.max(x1 + 20, (x1 + x2) / 2);
                const d =
                  x2 - x1 >= 30
                    ? `M ${x1} ${y1} H ${midX} V ${y2} H ${x2 - 5}`
                    : `M ${x1} ${y1} C ${x1 + 30} ${y1}, ${x2 - 30} ${y2}, ${x2 - 5} ${y2}`;
                return (
                  <path
                    key={`${e.from}-${e.to}`}
                    d={d}
                    fill="none"
                    stroke={e.critical ? '#dc2626' : '#64748b'}
                    strokeWidth={e.critical ? 2 : 1.4}
                    strokeDasharray={e.type === 'SS' ? '5 3' : undefined}
                    markerEnd={e.critical ? 'url(#pert-arrow-crit)' : 'url(#pert-arrow)'}
                  />
                );
              })}
              {pert.nodes.map((n) => {
                const p = nodePos(n.level, n.row);
                return (
                  <g key={n.id}>
                    <rect
                      x={p.x}
                      y={p.y}
                      width={NODE_W}
                      height={NODE_H}
                      rx={9}
                      fill={n.critical ? '#fef2f2' : '#ffffff'}
                      stroke={n.critical ? '#dc2626' : '#cbd5e1'}
                      strokeWidth={n.critical ? 2 : 1.2}
                    />
                    <text x={p.x + 10} y={p.y + 20} fontSize={12.5} fontWeight={600} fill="#0f172a">
                      {n.name.length > 21 ? `${n.name.slice(0, 20)}…` : n.name}
                    </text>
                    <text x={p.x + 10} y={p.y + 38} fontSize={11} fill="#475569">
                      E = {n.expected.toFixed(2)} hari
                    </text>
                    <text x={p.x + 10} y={p.y + 54} fontSize={11} fill="#475569">
                      O {n.optimistic} / M {n.mostLikely} / P {n.pessimistic}
                      {n.critical ? ' • KRITIS' : ''}
                    </text>
                  </g>
                );
              })}
            </svg>
          </div>
        </div>
      </div>
    </section>
  );
}

